{% doc %}
Renders a product card with studio imagery and variant links.
@param {product} product - Product to render
@param {boolean} [eager] - Whether to load the primary image eagerly
@param {boolean} [show_swatches] - Show color thumbnails
{% enddoc %}
{%- liquid
  assign card_image = product.featured_image
  assign card_title = product.title
  case product.handle
    when 'velantra-vivienne'
      assign card_title = 'VIVIENNE'
    when 'velantra-juliette'
      assign card_title = 'JULIETTE'
    when 'velantra-delphine'
      assign card_title = 'DELPHINE'
    when 'the-colette-wool-tote'
      assign card_title = 'COLETTE'
    when 'velantra-weekender', 'the-eleanor-weekender'
      assign card_title = 'ELEANOR'
    when 'velantra-margot-tote'
      assign card_title = 'MERIDIAN'
    when 'velantra-boat-tote-2'
      assign card_title = 'CAMILLE'
  endcase
  assign card_loading = 'lazy'
  if eager
    assign card_loading = 'eager'
  endif
-%}
{%- capture card_studio -%}{%- render 'studio-image-url', image: card_image, product: product -%}{%- endcapture -%}
{%- assign card_studio = card_studio | strip -%}
<article class="product-card" data-product-id="{{ product.id }}">
  <a class="product-card__media" href="{{ product.url }}" aria-label="{{ product.title | escape }}">
    {%- if card_studio != blank -%}
      <img src="{{ card_studio }}" alt="{{ product.title | escape }}" width="1200" height="1500" loading="{{ card_loading }}">
    {%- elsif card_image -%}
      {{ card_image | image_url: width: 1200 | image_tag: loading: card_loading, widths: '360,540,720,960,1200', sizes: '(min-width: 1000px) 25vw, 50vw', alt: product.title }}
    {%- else -%}
      {{ 'product-1' | placeholder_svg_tag: 'product-card__placeholder' }}
    {%- endif -%}
    {%- unless product.available -%}<span class="product-card__badge eyebrow">{{ 'commerce.product.sold_out' | t }}</span>{%- endunless -%}
  </a>
  <div class="product-card__info">
    <div class="product-card__heading">
      <h3><a href="{{ product.url }}" aria-label="{{ product.title | escape }}">{{ card_title | escape }}</a></h3>
      <p class="product-card__price{% if product.price == 0 %} product-card__price--availability{% endif %}">
        {%- render 'product-price', product: product -%}
      </p>
    </div>
    {%- if show_swatches != false and product.has_only_default_variant == false -%}
      <div class="product-card__swatches">
        {%- for option in product.options_with_values -%}
          {%- assign option_name = option.name | downcase -%}
          {%- if option_name == 'color' or option_name == 'colour' -%}
            {%- assign option_index = option.position | minus: 1 -%}
            {%- for value in option.values limit: 6 -%}
              {%- assign value_name = value.name | default: value -%}
              {%- assign swatch_variant = nil -%}
              {%- for variant in product.variants -%}{%- if variant.options[option_index] == value_name -%}{%- assign swatch_variant = variant -%}{%- break -%}{%- endif -%}{%- endfor -%}
              {%- if swatch_variant.featured_image -%}
                {%- capture swatch_studio -%}{%- render 'studio-image-url', image: swatch_variant.featured_image, product: product -%}{%- endcapture -%}
                {%- assign swatch_studio = swatch_studio | strip -%}
                <a href="{{ product.url }}?variant={{ swatch_variant.id }}" aria-label="{{ product.title | escape }} — {{ value | escape }}" title="{{ value | escape }}">
                  {%- if swatch_studio != blank -%}<img src="{{ swatch_studio }}" alt="{{ value | escape }}" width="72" height="90" loading="lazy">
                  {%- else -%}{{ swatch_variant.featured_image | image_url: width: 90 | image_tag: loading: 'lazy', alt: value }}{%- endif -%}
                </a>
              {%- endif -%}
            {%- endfor -%}
            {%- if option.values.size > 6 -%}<a class="product-card__more" href="{{ product.url }}">+{{ option.values.size | minus: 6 }}</a>{%- endif -%}
          {%- endif -%}
        {%- endfor -%}
      </div>
    {%- endif -%}
  </div>
</article>

{% doc %}
Renders native prices from the same variant, with accessible compare-at labels.
@param {product} product - Product to price
@param {variant} [variant] - Exact selected variant; omit for minimum/from pricing
@param {boolean} [show_currency] - Include the presentment currency code
{% enddoc %}
{%- liquid
  assign price_variant = variant
  assign show_from = false
  if price_variant == blank
    assign price_variant = product.variants | sort: 'price' | first
    assign show_from = product.price_varies
  endif
  assign show_compare = false
  if settings.show_compare_at_prices != false and price_variant.price > 0 and price_variant.compare_at_price > price_variant.price
    assign show_compare = true
  endif
  if show_currency
    assign current_price = price_variant.price | money_with_currency
    assign compare_price = price_variant.compare_at_price | money_with_currency
  else
    assign current_price = price_variant.price | money
    assign compare_price = price_variant.compare_at_price | money
  endif
-%}
{%- if price_variant != blank -%}
  <span class="price-display" data-price-display data-compare-enabled="{% if settings.show_compare_at_prices != false %}true{% else %}false{% endif %}" data-price-format="{% if show_currency %}currency{% else %}plain{% endif %}">
    <span data-price-status {% if price_variant.price > 0 %}hidden{% endif %}>{{ 'commerce.product.contact_availability' | t }}</span>
    <span class="price-display__values" data-price-values {% unless price_variant.price > 0 %}hidden{% endunless %}>
      <span class="price-display__current"><span class="visually-hidden">{{ 'commerce.product.current_price' | t }} </span><span data-price-current>{% if show_from %}{{ 'commerce.product.from_price' | t: price: current_price }}{% else %}{{ current_price }}{% endif %}</span></span>
      <span class="price-display__compare" data-price-compare-group {% unless show_compare %}hidden{% endunless %}><span class="visually-hidden">{{ 'commerce.product.compare_at_price' | t }} </span><s data-price-compare>{% if show_compare %}{{ compare_price }}{% endif %}</s></span>
    </span>
  </span>
{%- endif -%}
{% stylesheet %}
  .price-display { display: inline-block; max-width: 100%; }
  .price-display__values { display: inline-flex; align-items: baseline; justify-content: inherit; flex-wrap: wrap; gap: 3px 9px; max-width: 100%; }
  .price-display__current, .price-display__compare { display: inline-block; }
  .price-display__compare { color: var(--color-muted, #686861); }
  .price-display__compare s { text-decoration-thickness: 1px; }
  .price-display [hidden] { display: none !important; }
  .product-price .price-display__values { justify-content: center; }
  .product-card__price:has(.price-display) { flex-shrink: 1; min-width: 0; max-width: 55%; }
  .product-card__price .price-display__values { justify-content: flex-end; }
  .product-sticky > div:has(.price-display) { min-width: 0; }
  .product-sticky .price-display__values { gap: 2px 7px; }
  @media (max-width: 479px) {
    .product-card__heading:has(.price-display) { flex-wrap: wrap; gap: 6px 12px; }
    .product-card__heading:has(.price-display) h3 { flex-basis: 100%; }
    .product-card__price:has(.price-display) { max-width: 100%; text-align: left; }
    .product-card__price .price-display__values { justify-content: flex-start; }
  }
{% endstylesheet %}

{% doc %}Shared navigation, dialogs, video and Shopify cart behaviors.{% enddoc %}
<script>
(()=>{
const rawRoot=window.Shopify?.routes?.root || {{ routes.root_url | json }};const root=rawRoot.endsWith('/')?rawRoot:rawRoot+'/';const labels={empty:{{ 'cart.empty' | t | json }},shop:{{ 'general.view_collection' | t | json }},remove:{{ 'cart.remove' | t | json }},less:{{ 'cart.decrease' | t | json }},more:{{ 'cart.increase' | t | json }},error:{{ 'cart.error' | t | json }},pause:{{ 'general.pause' | t | json }},play:{{ 'general.play' | t | json }},preorderOctober:{{ settings.vivienne_preorder_message | json }},preorderEarlyOctober:{{ settings.colette_preorder_message | json }},preorderSeptember:{{ settings.weekender_black_preorder_message | json }}};
const money=v=>new Intl.NumberFormat({{ request.locale.iso_code | json }},{style:'currency',currency:{{ cart.currency.iso_code | default: shop.currency | json }}}).format(v/100);
const studioVariantImages={% render 'studio-variant-map' %};const cartImage=i=>studioVariantImages[String(i.variant_id)]||i.image;
const priorUpcartModifyCart=window.upcartModifyCart;window.upcartModifyCart=cart=>{const data=typeof priorUpcartModifyCart==='function'?(priorUpcartModifyCart(cart)||cart):cart;if(!Array.isArray(data?.items))return data;return {...data,items:data.items.map(item=>{const image=studioVariantImages[String(item.variant_id)];return image?{...item,image,featured_image:{...item.featured_image,url:image}}:item;})};};
const priorUpcartModifyUpsells=window.upcartModifyListOfUpsells;window.upcartModifyListOfUpsells=products=>{const data=typeof priorUpcartModifyUpsells==='function'?(priorUpcartModifyUpsells(products)||products):products;if(!Array.isArray(data))return data;return data.map(product=>{if(!Array.isArray(product.variants))return product;const variants=product.variants.map(variant=>{const src=studioVariantImages[String(variant.id)];return src?{...variant,featured_image:{...variant.featured_image,src}}:variant;});const first=variants.find(variant=>studioVariantImages[String(variant.id)]);return {...product,variants,featured_image:first?studioVariantImages[String(first.id)]:product.featured_image};});};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lastFocus;const open=id=>{if(id==='CartDrawer'&&typeof window.upcartOpenCart==='function'){document.querySelectorAll('dialog[open]').forEach(d=>d.close());window.upcartOpenCart();return;}const d=document.getElementById(id);if(!d)return;if(!document.querySelector('dialog[open]'))lastFocus=document.activeElement;document.querySelectorAll('dialog[open]').forEach(other=>{if(other!==d)other.close()});if(!d.open)d.showModal();if(id==='CartDrawer')refresh();};const close=d=>{d.close();lastFocus?.focus();};
document.addEventListener('click',e=>{const o=e.target.closest('[data-dialog-open]');if(o){e.preventDefault();open(o.dataset.dialogOpen)}const c=e.target.closest('[data-dialog-close]');if(c)close(c.closest('dialog'));if(e.target.matches('dialog[open]')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close(e.target)}if(!e.target.closest('.nav-dropdown'))document.querySelectorAll('.nav-dropdown[open]').forEach(d=>d.open=false)});
document.addEventListener('keydown',e=>{if(e.key!=='Escape')return;const d=document.querySelector('#NavigationDrawer[open],#SearchDialog[open],#LocaleDialog[open],#CartDrawer[open]');if(d){e.preventDefault();e.stopPropagation();close(d)}else{document.querySelectorAll('.nav-dropdown[open]').forEach(n=>{n.open=false;n.querySelector('summary')?.focus()})}},true);
document.addEventListener('cart:open',()=>open('CartDrawer'));
document.addEventListener('click',event=>{if(!window.Shopify?.designMode||event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;const checkout=event.composedPath().find(node=>node instanceof Element&&node.matches('.upcart-checkout-button[href]'));if(!checkout||checkout.getAttribute('aria-disabled')==='true')return;event.preventDefault();event.stopImmediatePropagation();window.open(checkout.href,'_blank','noopener');},true);

let upcartConnected=false;let upcartAttempts=0;let upcartTimer;
function connectUpcart(){if(upcartConnected)return true;if(typeof window.upcartSubscribeCartUpdated!=='function'||typeof window.upcartSubscribeCartLoaded!=='function'||typeof window.upcartSubscribeCartOpened!=='function')return false;const sync=event=>{if(!Array.isArray(event.cart?.items))return;const count=event.cart.items.reduce((sum,item)=>sum+Number(item.quantity||0),0);document.querySelectorAll('[data-cart-count]').forEach(n=>n.textContent=count);};window.upcartSubscribeCartUpdated(sync);window.upcartSubscribeCartLoaded(sync);window.upcartSubscribeCartOpened(()=>{document.querySelectorAll('dialog[open]').forEach(d=>d.close());});upcartConnected=true;return true;}
if(!connectUpcart())upcartTimer=setInterval(()=>{if(connectUpcart()||++upcartAttempts>=75)clearInterval(upcartTimer);},200);

function preorderNote(i){if({{ settings.vivienne_preorder | json }}&&i.handle==='velantra-vivienne')return labels.preorderOctober;if({{ settings.colette_preorder | json }}&&i.handle==='the-colette-wool-tote')return labels.preorderEarlyOctober;if({{ settings.weekender_black_preorder | json }}&&['velantra-weekender','the-eleanor-weekender'].includes(i.handle)&&i.variant_title==='Black')return labels.preorderSeptember;return '';}
let cartPending=0;let cartHasItems=false;
function checkoutState(){document.querySelectorAll('[data-cart-checkout]').forEach(button=>{button.disabled=cartPending>0||!cartHasItems;});}
function renderCart(cart){cartHasItems=cart.items.length>0;checkoutState();document.querySelectorAll('[data-cart-count]').forEach(n=>n.textContent=cart.item_count);const host=document.querySelector('[data-drawer-items]');if(!host)return;host.innerHTML=cart.items.length?cart.items.map(i=>`<article class="drawer-line">${cartImage(i)?`<img src="${esc(cartImage(i))}" width="100" height="125" alt="${esc(i.product_title)}">`:''}<div><h3><a href="${esc(i.url)}">${esc(i.product_title)}</a></h3><p>${i.variant_title?esc(i.variant_title):''}</p><p>${money(i.final_line_price)}</p>${preorderNote(i)?`<p class="drawer-preorder">${esc(preorderNote(i))}</p>`:''}<div class="drawer-quantity"><button data-cart-key="${esc(i.key)}" data-quantity="${i.quantity-1}" aria-label="${esc(labels.less)}">−</button><span>${i.quantity}</span><button data-cart-key="${esc(i.key)}" data-quantity="${i.quantity+1}" aria-label="${esc(labels.more)}">+</button><button class="drawer-remove" data-cart-key="${esc(i.key)}" data-quantity="0">${esc(labels.remove)}</button></div></div></article>`).join(''):`<div class="empty-state"><p>${esc(labels.empty)}</p><a href="${root}collections/handbags" class="text-link">${esc(labels.shop)}</a></div>`;document.querySelector('[data-drawer-total]').textContent=money(cart.total_price);document.querySelector('.cart-drawer-bottom').hidden=!cart.items.length;}
async function refresh(){cartPending++;checkoutState();try{const r=await fetch(root+'cart.js',{headers:{Accept:'application/json'},cache:'no-store'});if(!r.ok)throw Error();const cart=await r.json();renderCart(cart);document.querySelector('[data-cart-error]').textContent='';return cart}catch(e){cartHasItems=false;document.querySelector('[data-cart-error]').textContent=labels.error}finally{cartPending--;checkoutState()}}
document.addEventListener('cart:updated',e=>{if(e.detail?.items)renderCart(e.detail);else refresh()});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-cart-key]');if(!b||cartPending)return;cartPending++;checkoutState();const error=document.querySelector('[data-cart-error]');error.textContent='';document.querySelectorAll('[data-cart-key]').forEach(n=>n.disabled=true);try{const r=await fetch(root+'cart/change.js',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({id:b.dataset.cartKey,quantity:Number(b.dataset.quantity)})});const data=await r.json();if(!r.ok)throw Error(data.description||labels.error);renderCart(data);const nextButtons=[...document.querySelectorAll('[data-cart-key]')];const nextFocus=nextButtons.find(n=>n.dataset.cartKey===b.dataset.cartKey&&n.className===b.className&&n.getAttribute('aria-label')===b.getAttribute('aria-label'))||document.querySelector('#CartDrawer [data-dialog-close]');document.dispatchEvent(new CustomEvent('cart:updated',{detail:data}));const finalFocus=[...document.querySelectorAll('[data-cart-key]')].find(n=>n.dataset.cartKey===b.dataset.cartKey&&n.className===b.className&&n.getAttribute('aria-label')===b.getAttribute('aria-label'))||document.querySelector('#CartDrawer [data-dialog-close]');finalFocus?.focus()}catch(err){error.textContent=err.message}finally{cartPending--;checkoutState();document.querySelectorAll('[data-cart-key]').forEach(n=>n.disabled=false)}});
function videos(scope=document){scope.querySelectorAll('.hero-video,.detail-video').forEach(v=>{if(v.dataset.initialized)return;v.dataset.initialized='true';if(v.dataset.mobileSrc&&matchMedia('(max-width:767px)').matches){v.src=v.dataset.mobileSrc;v.poster={{ 'vivienne-hero-mobile.jpg' | asset_url | json }};v.load()}const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;if(reduce){v.autoplay=false;v.pause()}else v.play().catch(()=>{});const button=v.closest('.hero-film')?.querySelector('[data-video-toggle]');if(button){button.textContent=v.paused?labels.play:labels.pause;button.addEventListener('click',()=>{if(v.paused){v.play().catch(()=>{});button.textContent=labels.pause;button.setAttribute('aria-label',labels.pause)}else{v.pause();button.textContent=labels.play;button.setAttribute('aria-label',labels.play)}})}})}
videos();document.addEventListener('shopify:section:load',e=>videos(e.target));document.addEventListener('visibilitychange',()=>{if(document.hidden)document.querySelectorAll('.hero-video,.detail-video').forEach(v=>v.pause())});
})();
</script>

{% doc %}Global design tokens and the Velantra layout system.{% enddoc %}
<style>
@font-face{font-family:'Cormorant Garamond';font-style:normal;font-weight:400;font-display:swap;src:url({{ 'cormorant-400.ttf' | asset_url }}) format('truetype')}
@font-face{font-family:'Cormorant Garamond';font-style:normal;font-weight:500;font-display:swap;src:url({{ 'cormorant-500.ttf' | asset_url }}) format('truetype')}
@font-face{font-family:Montserrat;font-style:normal;font-weight:400;font-display:swap;src:url({{ 'montserrat-400.ttf' | asset_url }}) format('truetype')}
@font-face{font-family:Montserrat;font-style:normal;font-weight:500;font-display:swap;src:url({{ 'montserrat-500.ttf' | asset_url }}) format('truetype')}
@font-face{font-family:Montserrat;font-style:normal;font-weight:700;font-display:swap;src:url({{ 'montserrat-700.ttf' | asset_url }}) format('truetype')}
{% if settings.custom_fonts %}{% if settings.body_font != blank %}{{ settings.body_font | font_face: font_display: 'swap' }}{% endif %}{% if settings.heading_font != blank %}{{ settings.heading_font | font_face: font_display: 'swap' }}{% endif %}{% endif %}
:root{--font-serif:{% if settings.custom_fonts %}{{ settings.heading_font.family }},{{ settings.heading_font.fallback_families }}{% else %}'Cormorant Garamond',Georgia,serif{% endif %};--font-sans:{% if settings.custom_fonts %}{{ settings.body_font.family }},{{ settings.body_font.fallback_families }}{% else %}Montserrat,Arial,sans-serif{% endif %};--color-bg:{{ settings.color_background }};--color-text:{{ settings.color_text }};--color-line:{{ settings.color_line }};--color-muted:{{ settings.color_muted }};--studio-bg:{{ settings.studio_background }};--header-height:80px;--page-margin:12px;--space-section:{{ settings.section_spacing }}px}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:var(--header-height)}body{margin:0;background:var(--color-bg);color:var(--color-text);font-family:var(--font-sans);font-size:13px;font-weight:400;line-height:1.65}body:has(dialog[open]){overflow:hidden}button,input,select,textarea{font:inherit;color:inherit}button,a,input,select,textarea{-webkit-tap-highlight-color:transparent}button{cursor:pointer}button:disabled{cursor:not-allowed;opacity:.55}a{color:inherit;text-decoration:none}a:hover{text-decoration-color:currentColor}button{border:0;border-radius:0;background:none}input,textarea,select{border:1px solid var(--color-line);border-radius:0;background:transparent;padding:13px}input:focus,textarea:focus,select:focus{outline:1px solid var(--color-text);outline-offset:3px}a:focus-visible,button:focus-visible,summary:focus-visible{outline:2px solid currentColor;outline-offset:5px}img,video{max-width:100%;display:block}img{height:auto}h1,h2,h3,h4{font-family:var(--font-serif);font-weight:400;line-height:1.2;margin:0}h1,h2{font-size:clamp(26px,2.2vw,38px)}h3{font-size:25px}p{margin:0 0 18px}ul{padding-left:20px}summary{cursor:pointer;list-style:none}summary::-webkit-details-marker{display:none}[hidden]{display:none!important}.visually-hidden{position:absolute!important;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.skip-link{position:fixed;top:-100px;left:12px;z-index:1000;background:var(--color-text);color:var(--color-bg);padding:12px}.skip-link:focus{top:12px}.eyebrow,.micro{font-size:10px;font-weight:500;text-transform:uppercase;letter-spacing:1px;line-height:1.5}.eyebrow{margin-bottom:28px}.muted{color:var(--color-muted)}.page-width{max-width:{{ settings.page_width }}px;margin:auto;padding:0 var(--page-margin)}.button{display:inline-flex;justify-content:center;align-items:center;min-height:46px;padding:15px 32px;background:var(--color-text);color:var(--color-bg);border:1px solid var(--color-text);font-size:10px;font-weight:500;letter-spacing:1px;text-transform:uppercase;line-height:1.4;transition:background .2s,color .2s}.button:hover{background:var(--color-bg);color:var(--color-text)}.button--outline{background:transparent;color:var(--color-text)}.text-link{font-size:10px;text-transform:uppercase;letter-spacing:1px;padding-bottom:5px;border-bottom:1px solid currentColor}.rte p{margin-bottom:18px}.rte a{text-decoration:underline;text-underline-offset:4px}.rte h2,.rte h3{margin:32px 0 18px}.rte table{width:100%;border-collapse:collapse}.rte td,.rte th{padding:12px;border-bottom:1px solid var(--color-line)}.rte img{height:auto}.section-space{padding:var(--space-section) var(--page-margin)}.error{color:#963d35}.form-message{margin:14px 0;font-size:12px}dialog{border:0;margin:0;padding:0;background:var(--color-bg);color:var(--color-text);max-height:100dvh}dialog::backdrop{background:#0005}.dialog-top{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--color-line);padding:24px}.dialog-top h2{font-size:28px}.icon-close{font:300 28px/1 Arial;width:36px;height:36px;display:grid;place-items:center}.drawer{inset:0 0 0 auto;height:100dvh;width:min(500px,100%);max-width:100%}.drawer-body{padding:24px}.newsletter-input{display:flex;border-bottom:1px solid var(--color-line)}.newsletter-input input{flex:1;min-width:0;border:0;padding:16px 0}.newsletter-input button{padding:16px 0 16px 20px}.newsletter-consent{display:flex;gap:9px;text-align:left;font-size:10px;margin-top:18px}.newsletter-consent input{margin:3px 0 0}.newsletter-consent a{text-decoration:underline}.shopify-policy__container{max-width:760px!important;padding:64px 24px 100px!important}.shopify-policy__title{margin-bottom:42px!important}.shopify-policy__body{font-size:13px}.shopify-policy__body h2{margin-top:35px}.empty-state{text-align:center;padding:100px 20px}.empty-state h1{margin-bottom:24px}.pagination{display:flex;justify-content:center;gap:20px;padding:48px}.pagination a,.pagination .current{padding:7px 12px}.pagination .current{border-bottom:1px solid}.content-page{max-width:760px;margin:auto;padding:75px 24px 110px}.content-page>h1{margin-bottom:42px;text-align:center}.contact-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.contact-grid label{display:grid;gap:8px}.contact-grid .full{grid-column:1/-1}.contact-grid textarea{min-height:150px}.blog-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.blog-grid article img{aspect-ratio:4/5;object-fit:cover;width:100%;margin-bottom:20px}.blog-grid h2{font-size:25px;margin:10px 0}.article-hero{margin-bottom:40px}.announcement{padding:8px 16px;text-align:center;font-size:10px;letter-spacing:1px}
@media(max-width:767px){:root{--header-height:64px;--space-section:64px}.button{min-height:48px}input,textarea,select{font-size:16px}.blog-grid{grid-template-columns:1fr}.contact-grid{grid-template-columns:1fr}.contact-grid .full{grid-column:auto}.section-space{padding:64px 20px}.content-page{padding-top:45px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}
</style>

